import heapq


def rounded(numerator, denominator, mode):
    if mode == "half_up":
        return (numerator + denominator // 2) // denominator
    return numerator // denominator


def ledger(data, revision_first, original_tax):
    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if revision_first:
            key = (event.get("revision", 0), pos)
        else:
            key = (sequence, event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, mode)
        base = raw if original_tax else net
        tax = rounded(base * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def resolve_packages(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})

    domains = []
    for name in names:
        versions = sorted({row["version"] for row in packages[name]}, reverse=True)
        domains.append([-1] + versions)

    for vector in product(*domains):
        selected = {name: version for name, version in zip(names, vector)
                    if version != -1}
        valid = True
        for name, bounds in roots.items():
            version = selected.get(name)
            if version is None or not bounds[0] <= version <= bounds[1]:
                valid = False
                break
        if not valid:
            continue
        for name, version in selected.items():
            if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                valid = False
                break
        if not valid:
            continue

        rows = {}
        edges = {name: [] for name in selected}
        for name, version in selected.items():
            row = next((r for r in packages[name] if r["version"] == version), None)
            if row is None:
                valid = False
                break
            rows[name] = row
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = selected.get(dep["name"])
                if target is None or not dep["min"] <= target <= dep["max"]:
                    valid = False
                    break
                edges[name].append(dep["name"])
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, []))
        if reachable != set(selected):
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            if any(not visit(other) for other in edges.get(name, [])):
                return False
            state[name] = 2
            return True
        if not all(visit(name) for name in selected):
            continue
        return {"versions": selected}
    return {"error": "unsatisfiable"}


def schedule_jobs(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    options = [job for job in jobs if job["id"] not in blocked]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best = None

    for subset in combinations(options, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        if any(sum(job["start"] <= t < job["end"] for job in subset) > 2
               for t in {job["start"] for job in subset}):
            continue
        selected = sorted(ids)
        value = sum(job["value"] for job in subset)
        candidate = (value, selected)
        if best is None or value > best[0] or (value == best[0] and selected < best[1]):
            best = candidate
    if best is None:
        return {"error": "impossible"}
    return {"selected": best[1], "value": best[0]}


def temporal_route(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit.get(data["source"], 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start_state = (data["source"], initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"], data["source"], initial_mask, data["coupons"])]
    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, remaining - 1))
            next_mask = mask | bit.get(edge["v"], 0)
            for duration, next_remaining in choices:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_remaining)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, edge["v"], next_mask,
                                           next_remaining))
    return {"arrival": None}


